import{feedbackFigure,tropismFigure,cuttingFigure,ripeningFigure}from './growth-figures.js?v=20261023-physicscomplete01';
export const growthFilms={
'growth-feedback':{title:'Thyroxine: close the control loop',steps:['Low thyroxine reduces inhibitory feedback.','Pituitary stimulation of the thyroid increases.','The thyroid secretes more thyroxine.','The rise inhibits further stimulation, opposing the original change.'],duration:14,note:'Simplified GCSE negative feedback. Signal tracer and timing are symbolic, not measured concentrations. Pituitary stimulation is shown without requiring detailed regulatory-hormone names. Thyroxine supports basal metabolism, growth and development. Adrenaline is a separate stress response.',render:p=>feedbackFigure({progress:p})},
'growth-tropism':{title:'Watch unequal growth bend a shoot',steps:['One-sided light provides a directional stimulus.','Auxin becomes unevenly distributed towards the shaded side.','Shaded-side shoot cells elongate more.','The shoot curves towards the light.'],duration:12,note:'Compressed growth sequence, not a rotating rigid seedling or measured time-lapse. Cell widths, auxin dots and bend are exaggerated. Inspection compares left/right light and root/shoot gravity responses; roots respond differently to auxin.',render:p=>tropismFigure({progress:p,state:'left',kind:'light'})},
'growth-cutting':{title:'A cutting establishes roots',steps:['A suitable plant cutting is prepared.','Auxin rooting powder is applied at the base.','Roots form over time in suitable conditions.','Roots take up water as the cutting establishes.'],duration:13,note:'Worked developmental sequence, not a product application protocol or guaranteed outcome. Root emergence and timing are schematic. Auxin is a signal, not food; suitable conditions are still needed.',render:p=>cuttingFigure({progress:p})},
'growth-ripening':{title:'Ethene and progressive fruit ripening',steps:['Fruit is at an earlier developmental stage.','Ethene signalling helps coordinate ripening.','Ripening progresses over time.','Readiness can be coordinated with transport and sale.'],duration:13,note:'Symbolic fruit colour and compressed timing; not a universal colour test, dose or shelf-life prediction. Ethene also controls cell division. Gibberellin germination is a different process, available in the paired inspection activities.',render:p=>ripeningFigure({progress:p})}
};
growthFilms['growth-adrenaline']={title:'Adrenaline: prepare for action',steps:['Fear or stress triggers a response.','Adrenal glands release adrenaline into blood.','The hormone reaches target tissues.','Heart rate and delivery of oxygen and glucose increase.'],duration:12,note:'Schematic hormone signalling, not a clinical timing or dose model. Hormone particles and paths are symbolic; oxygen/glucose delivery supports respiration.',render:p=>feedbackFigure({progress:p,kind:'adrenaline'})};
for(const root of[false,true])growthFilms[root?'growth-root-gravity':'growth-shoot-gravity']={title:root?'A root curves downwards':'A shoot curves upwards',steps:['A newly germinated organ is horizontal.','Auxin accumulates on its lower side.',root?'Higher auxin inhibits elongation on the lower side.':'Auxin promotes elongation on the lower side.',root?'The upper side grows more; the root curves down.':'The lower side grows more; the shoot curves up.'],duration:12,note:'Gravity points down. Unequal growth is compressed and exaggerated; the organ is not a rigid rotating rod. Root and shoot responses differ.',render:p=>tropismFigure({progress:p,kind:'gravity',state:root?'root':'shoot'})};
growthFilms['growth-germination']={title:'Gibberellin and seed germination',steps:['A dormant seed is present.','Gibberellin helps end dormancy.','Suitable water, oxygen and temperature support growth.','The root and shoot emerge during germination.'],duration:13,note:'Developmental summary; detailed molecular mechanism is outside this GCSE scope. The seed is not guaranteed to germinate and hormone does not replace suitable conditions. Time and shape are schematic.',render:p=>cuttingFigure({progress:p,kind:'germination'})};
